// Count BTNC presses on the LEDs; BTNU clears the count.
module top #(
  parameter CLK_HZ = 100_000_000
) (
  input         clk,
  input         btnC,    // count: 1 while pressed
  input         btnU,    // clear
  output [15:0] led
);
  // Clock cycles a new button level must hold before we believe it.
  localparam SETTLE = CLK_HZ / 1000 * {{p:settle}};

  // 1. Synchronise: two flip-flops bring btnC onto our clock.
  reg [1:0] sync = 2'b00;
  always @(posedge clk) sync <= {sync[0], btnC};

  // 2. Debounce: follow the button only once it has been steady for SETTLE cycles.
  reg        clean = 1'b0;
  reg [31:0] held  = 0;
  always @(posedge clk) begin
    if (sync[1] == clean)
      held <= 0;
    else if (held == SETTLE - 1) begin
      clean <= sync[1];
      held  <= 0;
    end else
      held <= held + 1;
  end

  // 3. Edge: a pulse one clock long when the clean level goes from 0 to 1.
  reg  was = 1'b0;
  always @(posedge clk) was <= clean;
  wire press = clean & ~was;

  // 4. Count the pulses; BTNU wins.
  reg [15:0] count = 0;
  always @(posedge clk) begin
    if (btnU)
      count <= 0;
    else if (press)
      count <= count + 1;
  end

  assign led = count;
endmodule

